{
  "claims": [
    {
      "quote": "The official India retail box for CloudNote Air includes a wall charging adapter, even though separate accessory lists may make the charging arrangement look less obvious.",
      "label": "contradicted",
      "fact_ids": [
        "cloudnote.air.adapter_included"
      ],
      "reason": "The official India retail box for CloudNote Air does not include a wall charging adapter."
    },
    {
      "quote": "The manufacturer supports a stereo pair made from one CloudNote Air and one CloudNote Studio, since being members of the same brand is sufficient for cross-model stereo compatibility.",
      "label": "contradicted",
      "fact_ids": [
        "cloudnote.air.stereo_pairing_scope",
        "cloudnote.studio.stereo_pairing_scope"
      ],
      "reason": "Both models only support stereo pairing with units of the same model, and cross-model pairing is unsupported."
    },
    {
      "quote": "Turning CloudNote Air up from fifty to one hundred percent volume in the stated new-battery, EQ-off laboratory tests halves its listed playback time from 10 hours to 5 hours.",
      "label": "supported",
      "fact_ids": [
        "cloudnote.air.battery_50_percent",
        "cloudnote.air.battery_100_percent"
      ],
      "reason": "The laboratory tests confirm 10 hours at 50% volume and 5 hours at 100% volume."
    },
    {
      "quote": "For a current India catalogue comparison before shipping, CloudNote Air is INR 1,500 more expensive than CloudNote Studio, with tax included in both listed prices.",
      "label": "contradicted",
      "fact_ids": [
        "cloudnote.air.price_2026",
        "cloudnote.studio.price_2026"
      ],
      "reason": "CloudNote Air (1,499 INR) is less expensive than CloudNote Studio (2,999 INR), not 1,500 INR more expensive."
    },
    {
      "quote": "For an India purchase at the official catalogue list price on 1 October 2026, CloudNote Air costs INR 1,499 including tax but excluding shipping.",
      "label": "supported",
      "fact_ids": [
        "cloudnote.air.price_2026"
      ],
      "reason": "The stated price matches the catalogue fact for the year 2026."
    },
    {
      "quote": "Considering the speaker alone and leaving retail packaging and accessories out of the measurement, CloudNote Air has a stated mass of 0.35 kilograms for carrying-weight comparisons.",
      "label": "supported",
      "fact_ids": [
        "cloudnote.air.weight"
      ],
      "reason": "350 grams is equal to 0.35 kilograms."
    },
    {
      "quote": "Water damage to CloudNote Air is included in the standard India manufacturer warranty after an authorized purchase, because water resistance should be understood as warranty coverage rather than just a product capability.",
      "label": "contradicted",
      "fact_ids": [
        "cloudnote.air.water_damage_covered"
      ],
      "reason": "Water damage is explicitly not covered by the standard India manufacturer warranty."
    }
  ]
}

{
  "claims": [
    {
