    },
    {
      "quote": "In the 2025 India catalogue, before the current-year revision, ClearTrail Plus already carried the same tax-inclusive list price of INR 2,499, excluding shipping from that amount.",
      "label": "contradicted",
      "fact_ids": ["cleartrail.plus.price_2025"],
      "reason": "The fact states the 2025 price for ClearTrail Plus was 2,199 INR, not 2,499 INR."
    }
  ]
}

{
  "claims": [
    {
